class DiskCache:
    """A tiny JSON-on-disk cache with per-entry TTL."""

    def __init__(self, root: str, ttl: float, now=time.time):
        self.root = root
        self.ttl = ttl
        self._now = now
        os.makedirs(root, exist_ok=True)

    def _path(self, key):
        return os.path.join(self.root, f"{key}.json")

    def set(self, key, value):
        with open(self._path(key), "w") as f:
            json.dump({"t": self._now(), "v": value}, f)

    def get(self, key, default=None):
        p = self._path(key)
        if not os.path.exists(p):
            return default
        try:
            with open(p) as f:
                rec = json.load(f)
        except Exception:
            # If the file is corrupt/unreadable treat as missing
            try:
                os.remove(p)
            except Exception:
                pass
            return default

        # If record doesn't have a timestamp or value, treat as missing
        t = rec.get("t")
        if t is None:
            try:
                os.remove(p)
            except Exception:
                pass
            return default

        # If the entry is expired, remove the file and return default
        if self._now() - t > self.ttl:
            try:
                os.remove(p)
            except Exception:
                pass
            return default

        return rec.get("v", default)

